import { MongoClient } from "mongodb";
//#region src/lib/mongodb.ts
var uri = process.env.MONGODB_URI || process.env.MONGO_URI || "";
var clientPromise = null;
function getClientPromise() {
	if (!uri) return null;
	if (!clientPromise) {
		const globalWithMongo = global;
		if (!globalWithMongo._mongoClientPromise) globalWithMongo._mongoClientPromise = new MongoClient(uri).connect();
		clientPromise = globalWithMongo._mongoClientPromise;
	}
	return clientPromise;
}
async function getDb(dbName = "kotlin_edu") {
	const promise = getClientPromise();
	if (!promise) throw new Error("No MongoDB URI configured. Set MONGODB_URI or MONGO_URI in .env.local");
	return (await promise).db(dbName);
}
/** Returns null instead of throwing when MongoDB is unavailable */
async function getDbSafe(dbName = "kotlin_edu") {
	try {
		return await getDb(dbName);
	} catch {
		return null;
	}
}
//#endregion
export { getDbSafe };
